function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Oklahoma OK-W-4");
  c.bool(form, "exempt");
  if (form.exempt) return;
  c.oneOf(form, "filingStatus", ["single", "married", "marriedWithholdAtSingle"]);
  c.nonNegInt(form, "allowances");
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  if (!period) throw new Error(`Oklahoma has no percentage table for ${payPeriodsPerYear} pay periods a year`);
  const has = onFile(form);
  if (has && form.exempt) return { stateCents: 0, formBasis: "ok-w-4-exempt", lines: {} };
  const status = has && form.filingStatus === "married" ? "married" : "single";
  const allowances = has ? form.allowances ?? 0 : 0;
  const net = Math.max(0, wagesCents - allowances * t.allowanceCents[period]);
  const tax = fromBaseTable(net, t.percentageTables[period][status]);
  const extra = has ? form.additionalWithholdingCents ?? 0 : 0;
  return {
    stateCents: Math.round(tax / 100) * 100 + extra,
    formBasis: has ? "ok-w-4" : "none-on-file-single-zero",
    lines: { period, status, netCents: net, taxCents: tax },
  };
}

module.exports = {
  code: "OK",
  name: "Oklahoma",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
